select * from jsonb_populate_recordset(null::public.temples, $rtam$[{"id":"00248b35-dd2f-4da3-8c19-4a9039821724","name":"Siddhivinayak Temple, Siddhatek","deity":"Siddhivinayak (Ganesha)","sampradaya":"Ganapatya","significance":["Ashtavinayak"],"country":"India","state":"Maharashtra","district":"Ahmednagar","town":"Siddhatek","latitude":18.5667,"longitude":74.9833,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Bhima","river_distance_km":0.2,"best_season_notes":"Ganesh Chaturthi (Aug–Sep) is the busiest day; Oct–Feb otherwise for the Ashtavinayak circuit.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-04T13:05:55.016033+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"Tradition holds this is where Vishnu meditated on Ganesha to gain the siddhi (spiritual power) needed to defeat the demons Madhu and Kaitabha, giving the deity here the name Siddhivinayak. The idol's trunk turns to the right rather than the more common left, a form considered more powerful and traditionally observed with stricter ritual discipline (including a longer period of abstinence for worshippers).","etiquette_notes":null,"native_name":"श्री सिद्धिविनायक मंदिर","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Pune International Airport","nearest_airport_distance_km":112.1,"nearest_railway_station_name":"Jinti Road railway station","nearest_railway_distance_km":29.1,"emergency_contact_notes":null,"sthala_purana_source":"Local/regional tradition, drawing on the Ganesha Purana","architecture_style":null,"construction_century":null},{"id":"00259fff-2a38-4bde-bd8d-c53fcd255feb","name":"Kankalitala Temple","deity":"Kankalini (Devi)","sampradaya":"Shakta","significance":["Shakti Peetha"],"country":"India","state":"West Bengal","district":"Birbhum","town":"Kankalitala","latitude":23.6167,"longitude":87.6667,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Kopai","river_distance_km":0.1,"best_season_notes":"Oct–Feb; Navaratri and Kali Puja draw the largest crowds.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-04T18:27:49.795249+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"One of the 51 Shakti Peethas, on the banks of the Kopai river, where tradition holds Sati's waist (or, by some accounts, her bones — kankal) fell after Vishnu's discus cut apart her body to end Shiva's grief-stricken tandava. Unusually plain among the Shakti Peethas, the temple holds no metal, clay, or stone idol, worshipping instead at the sacred kund said to mark the spot itself.","etiquette_notes":null,"native_name":"কঙ্কালীতলা মন্দির","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Kazi Nazrul Islam Airport","nearest_airport_distance_km":43.3,"nearest_railway_station_name":"Bhedia railway station","nearest_railway_distance_km":5.4,"emergency_contact_notes":null,"sthala_purana_source":"Local/regional tradition","architecture_style":null,"construction_century":null},{"id":"003cc2ca-855f-4569-9ce8-73f9e4236e23","name":"Thyagaraja Temple, Tiruvottiyur","deity":"Shiva as Thyagaraja","sampradaya":"Shaiva","significance":[],"country":"India","state":"Tamil Nadu","district":"Chennai","town":"Zone 1 Tiruvottiyur","latitude":13.1609,"longitude":80.2992,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Kortallaiyar River","river_distance_km":2.7,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:38.937899+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A Tevaram-praised Shiva temple in northern Chennai, also called Vadivudai Amman Temple, linked with Sundarar and Pattinathar. It dates from Pallava times and was expanded by the Cholas in the 11th century. It has a seven-tiered gateway tower and a tank, and is listed among the 51 Sakthi Peetams.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Chennai International Airport","nearest_airport_distance_km":23.5,"nearest_railway_station_name":"Tiruvottiyur railway station","nearest_railway_distance_km":0.3,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Thyagaraja Temple, Tiruvottiyur), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":7},{"id":"0070640f-79d1-4a44-8763-3af53f4f1a35","name":"Tirunageswaram Naganathar Temple","deity":"Naganathar (Shiva)","sampradaya":"Shaiva","significance":["Navagraha Sthalam"],"country":"India","state":"Tamil Nadu","district":"Thanjavur","town":"Thirunageswaram","latitude":10.96428,"longitude":79.42927,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Cauvery","river_distance_km":2,"best_season_notes":"Oct–Feb; Sundays are considered auspicious for Rahu worship here.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-05T11:47:03.785954+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"The Navagraha Sthalam for Rahu, also known as the Rahu Sthalam. Tradition holds that serpents — including Adishesha, Takshaka and Karkotaka — worshipped Shiva at this spot, giving the temple its name (Thiru-naga-eswaram, \"the lord of serpents\"). Believed built by the Chola king Aditya I in the 10th century, with later royal additions, and venerated as a Paadal Petra Sthalam in the Tevaram.","etiquette_notes":null,"native_name":"நாகநாதர் கோயில், திருநாகேஸ்வரம்","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Thanjavur Air Force Station","nearest_airport_distance_km":44,"nearest_railway_station_name":"Kumbakonam railway station","nearest_railway_distance_km":4.4,"emergency_contact_notes":null,"sthala_purana_source":"Tevaram canon; local/regional tradition","architecture_style":"Dravidian (Chola)","construction_century":10},{"id":"00c0722c-f75f-4dc1-b6df-6983dbcfc828","name":"Brahma Temple, Bramha Karmali","deity":"Brahma","sampradaya":null,"significance":[],"country":"India","state":"Goa","district":"North Goa","town":"Ambedem","latitude":15.56954,"longitude":74.16267,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Kotrachi River","river_distance_km":2,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:05:20.030396+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"One of the few temples dedicated to Brahma in India, located in Nagargao village near Valpoi, Goa. It holds a black stone idol from the Kadamba period, carved in the 12th century. The figure shows Brahma, bearded, in a Trimurti form that represents Brahma, Vishnu and Mahesh.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Manohar International Airport","nearest_airport_distance_km":37.1,"nearest_railway_station_name":"Castle Rock railway station","nearest_railway_distance_km":26.4,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Brahma Temple, Bramha Karmali), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":12},{"id":"00cbd105-08d4-4ebf-b6b5-f575264316c2","name":"Chhatarpur Mandir (Shri Aadya Katyayani Shakti Peeth), Delhi","deity":"Katyayani — a form of Durga","sampradaya":"Shakta","significance":[],"country":"India","state":"Delhi","district":"South Delhi","town":"Chhatarpur","latitude":28.5019,"longitude":77.1794,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Yamuna River","river_distance_km":13.5,"best_season_notes":"Navratri, held twice a year, is the major festival and draws very large crowds, with a community kitchen (langar) running for visitors.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-25T13:54:12.118115+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"Established in 1974 by Baba Sant Nagpal ji, who died in 1998 and whose samadhi is within the complex. A large modern temple complex rather than an ancient site.","etiquette_notes":"Photography is not permitted in the prayer hall. The Katyayani shrine is opened only during the two Navratri periods.","native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"t